        return correspondencia.group(1)
    return valor"}

{"codigo":"def corrigir(valor):
    if valor == "":
        return valor
    numero = float(valor.removesuffix("%"))
    novo_valor = f"{numero:.3f}".rstrip("0").rstrip(".")
    return novo_valor"}

